import json

test_input = [[[0, 0, 0, 3, 1, 0, 3, 3, 3], [0, 3, 3, 0, 1, 0, 3, 3, 0], [3, 0, 3, 0, 1, 0, 3, 0, 3], [3, 3, 0, 0, 1, 0, 3, 3, 3]]]
test_output = [[8, 8, 8, 8, 3, 8, 3, 3, 8], [3, 8, 8, 8, 3, 8, 3, 8, 3]]

# Full analysis for ALL columns
print("=== FULL COLUMN ANALYSIS ===")

for col in range(9):
    pairs = []
    for r in range(2):
        a = test_input[0][r*2][col]
        b = test_input[0][r*2+1][col]
        out = test_output[r][col]
        pairs.append((a, b, out))

    # Group by input pair
    by_pair = {}
    for a, b, out in pairs:
        key = (a, b)
        if key not in by_pair:
            by_pair[key] = []
        by_pair[key].append(out)

    # Most common output (mode)
    modes = {}
    for (a,b), outs in by_pair.items():
        # Count each output
        count = {}
        for o in outs:
            count[o] = count.get(o, 0) + 1
        max_count = max(count.values())
        mode = [k for k,v in count.items() if v == max_count][0]
        modes[(a,b)] = mode

    print(f"\nCol {col}: {pairs}")
    print(f"  By pair {by_pair}: {modes}")

# Try to find rule for when output = 3
print("\n=== OUTPUT = 3 CASES ===")
for r in range(2):
    for c in range(9):
        a = test_input[0][r*2][c]
        b = test_input[0][r*2+1][c]
        out = test_output[r][c]
        if out == 3:
            print(f"r={r}, c={c}: input ({a},{b}) -> 3")

import json

json_file = "/home/USER/runs/paper/qwen-hpl-u1-turns/frozen/seen-4/play/users/u047/system/state/workspace/programs/task-c844dc0c.json"
with open(json_file) as f:
    data = json.load(f)

demos = data['demos']
demo = demos[0]
input_grid = demo['input']
output_grid = demo['output']

def transform_simple(grid):
    n_out = len(grid) // 2
    result = []
    for r in range(n_out):
        out_row = []
        for c in range(len(grid[r])):
            a, b = grid[2*r][c], grid[2*r+1][c]
            if a == b and a != 0:
                out_row.append(3)
            else:
                out_row.append(8)
        result.append(out_row)
    return result

result = transform_simple(input_grid)

print("=== 23x2 -> 11x2 DEMO CASE ===")
print("Expected output:")
for r, row in enumerate(output_grid):
    print(f"  r={r}: {row}")

print("\nMy simple rule output:")
for r, row in enumerate(result):
    print(f"  r={r}: {row}")

# Compare
mismatches = []
for r in range(11):
    for c in range(2):
        if result[r][c] != output_grid[r][c]:
            mismatches.append(f"({r},{c}): got {result[r][c]}, expected {output_grid[r][c]}")

if mismatches:
    print(f"\nMISMATCHES ({len(mismatches)}):")
    for m in mismatches:
        print(f"  {m}")
else:
    print("\n✓ PERFECT MATCH!")

