def pprint(data, indent=0):
    prefix = "  " * indent
    if isinstance(data, dict):
        for k, v in data.items():
            print(f"{prefix}{k}:")
            pprint(v, indent+1)
    elif isinstance(data, list):
        if len(data) == 0:
            print(f"{prefix}[]")
        elif all(isinstance(x, int) for x in data[:3]):
            print(f"{prefix}[{len(data)} values]", end="")
            if len(data) <= 10:
                print(f" = {data}")
            else:
                print(f"... ({data[0]}, ..., {data[-1]})")
        else:
            print(f"{prefix}[{len(data)} elements]")
            for i, v in enumerate(data[:5]):
                print(f"{prefix}  [{i}]: {v}")
            if len(data) > 5:
                print(f"{prefix}  ...")

